function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 300) return 'nums needs 1 to 300 rows.';
  const width = nums[0].length;
  if (width < 1 || width > 500) return 'Each row needs 1 to 500 values.';
  for (const row of nums) {
    if (row.length !== width) return 'Every row must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 0 || v > 1000)) return 'Each value is an integer from 0 to 1000.';
  }
  return null;
}

