function matrixSum(nums) {
  for (const row of nums) {
    row.sort((a, b) => b - a);
  }
  let score = 0;
  for (let col = 0; col < nums[0].length; col++) {
    let largest = 0;
    for (const row of nums) {
      largest = Math.max(largest, row[col]);
    }
    score += largest;
  }
  return score;
}

