function matrixSum(nums) {
  const rows = nums.map(row => row.slice());
  let total = 0;
  while (rows[0].length > 0) {
    let roundMax = -1;
    for (const row of rows) {
      let at = 0;
      for (let j = 1; j < row.length; j++) if (row[j] > row[at]) at = j;
      roundMax = Math.max(roundMax, row[at]);
      row.splice(at, 1);
    }
    total += roundMax;
  }
  return total;
}

